#include <bits/stdc++.h>
using namespace std;

const int maxn = 3005;

struct node {
    long long r, l;

    node(long long r, long long l) : r(r), l(l) {}
    node() : r(0), l(0) {}

    bool operator<(const node& o) const {
        if (r == o.r) return l < o.l;
        return r < o.r;
    }

    node operator+(const node& o) const {
        return node(r + o.r, l + o.l);
    }
} dp[maxn][maxn], g[maxn];

vector<int> E[maxn];
long long siz[maxn], w[maxn], b[maxn];
int n, m;

void dfs(int x, int fa) {
    dp[x][1] = node(0, w[x] - b[x]);
    if (dp[x][1].l > 0) dp[x][1].r++;

    siz[x] = 1;

    for (int i : E[x]) {
        if (i == fa) continue;

        dfs(i, x);

        for (int j = 1; j <= m; j++) g[j] = node(-1, 0);

        for (int j = 1; j <= siz[x]; j++) {
            for (int k = 1; k <= siz[i]; k++) {
                node t1 = dp[i][k];
                node t2 = dp[i][k];

                if (dp[x][j].l > 0 && t1.l > 0) t1.r--;
                if (dp[x][j].l + t1.l <= 0 &&
                    (dp[x][j].l > 0 || t1.l > 0)) {
                    t1.r--;
                }

                t2.l = 0;

                g[j + k - 1] = max(g[j + k - 1], dp[x][j] + t1);
                g[j + k] = max(g[j + k], dp[x][j] + t2);
            }
        }

        siz[x] += siz[i];

        for (int j = 1; j <= siz[x]; j++) {
            dp[x][j] = g[j];
        }
    }
}

